#!/usr/bin/env bash
# Tipografía Ecard y avisos de nuevos aliados. Publicación sin SQL, red o mensajes.
set -euo pipefail
MODE="${1:---check}"
[[ ( "$#" -le 1 && ( "$MODE" == --check || "$MODE" == --apply ) ) || ( "$MODE" == --restore && "$#" == 2 ) ]] || { echo 'Uso: --check | --apply | --restore RUTA' >&2;exit 2; }
VERSION='ecard-aliados-v1'
FILES=('app/services/EcardReunionService.php' 'app/controllers/ReminderController.php' 'app/controllers/AliadoController.php' 'app/views/layout/topbar.php' 'app/services/AliadoNuevoNotificationService.php' 'tools/configurar_avisos_aliados.php')
LIVE="${IMPE_CORREOS_PUBLIC:-$HOME/domains/fundacionrededumex.org/public_html}"
BACKUPS="${IMPE_CORREOS_BACKUPS:-$HOME/respaldos-crm}"
fail(){ echo "ERROR: $*" >&2;exit 1; }
hash(){ sha256sum "$1" | cut -d' ' -f1; }
state(){ if [[ -f "$1" ]];then hash "$1";elif [[ ! -e "$1" && ! -L "$1" ]];then echo AUSENTE;else fail 'Destino incompatible.';fi; }
no_links(){ local part="$1";while [[ "$part" != / && "$part" != . ]];do
 [[ ! -L "$part" ]] || fail "Enlace simbólico no permitido: $1"
 case "$part" in */*) part="${part%/*}";[[ -n "$part" ]] || part=/;; *) part=.;;esac
done; }
for tool in php sha256sum cut mktemp realpath cp mv mkdir rm rmdir dirname date chmod;do command -v "$tool" >/dev/null || fail "Falta $tool";done
no_links "$LIVE";[[ -d "$LIVE" ]] || fail 'Raíz del CRM no encontrada.'
LIVE="$(cd "$LIVE" && pwd -P)";[[ -f "$LIVE/index.php" ]] || fail 'Falta el índice del CRM.'
for file in "${FILES[@]}";do no_links "$LIVE/$file";done
for i in 0 1 2 3;do [[ -f "$LIVE/${FILES[$i]}" ]] || fail "Falta ${FILES[$i]}";done
if [[ "$MODE" != --restore ]];then
 php -r '$r=$argv[1];foreach(["imagettftext","imagettfbbox","imagecreatefromstring","imagejpeg"] as $f){if(!function_exists($f))exit(2);}foreach(["DejaVuSans.ttf","DejaVuSans-Bold.ttf"] as $f){$p=$r."/vendor/dompdf/dompdf/lib/fonts/".$f;if(!is_file($p)||@imagettfbbox(24,0,$p,"Reunión México")===false)exit(2);}echo "OK: FreeType y fuentes locales de Ecard disponibles.\n";' "$LIVE" || fail 'Faltan FreeType o fuentes de Dompdf. SITIO INTACTO.'
fi
no_links "$BACKUPS";BACKUPS="$(realpath -m "$BACKUPS")"
[[ "$BACKUPS" != / && "$BACKUPS/" != "$LIVE/"* && "$LIVE/" != "$BACKUPS/"* ]] || fail 'El respaldo debe estar fuera del sitio y sus antecesores.'
SCRATCH="$(cd "${TMPDIR:-/tmp}" && pwd -P)";[[ "$SCRATCH/" != "$LIVE/"* ]] || fail 'Temporales fuera del sitio requeridos.'
TMP="$(mktemp -d "$SCRATCH/impe-ecard-aliados.XXXXXX")"
LOCK="$(dirname "$LIVE")/.impe-correos-deploy.lock";LOCKED=0;INSTALLING=-1
BEFORE=();AFTER=();WRITTEN=();CHANGED=()
finish(){ local code=$?;trap - EXIT INT TERM
 if [[ "$code" != 0 ]];then
  for i in "${WRITTEN[@]}";do
   if [[ "$(state "$LIVE/${FILES[$i]}")" == "${AFTER[$i]}" ]];then
    if [[ "${BEFORE[$i]}" == AUSENTE ]];then rm -f -- "$LIVE/${FILES[$i]}";else cp -p -- "$TMP/original.$i" "$LIVE/${FILES[$i]}" || echo 'REVISAR RESTAURACIÓN DEL ARCHIVO' >&2;fi
   else echo "REVISAR: archivo cambiado durante la publicación: ${FILES[$i]}" >&2;fi
  done
 fi
 if [[ "$INSTALLING" != -1 ]];then rm -f -- "$LIVE/${FILES[$INSTALLING]}.impe-ecard-aliados-$$";fi
 [[ "$LOCKED" == 0 ]] || rmdir -- "$LOCK"
 for i in "${!FILES[@]}";do rm -f -- "$TMP/original.$i" "$TMP/stage.$i";done
 rm -f -- "$TMP/patch.php"
 rmdir -- "$TMP";exit "$code"
}
trap finish EXIT;trap 'exit 130' INT;trap 'exit 143' TERM
if [[ "$MODE" != --check ]];then no_links "$LOCK";mkdir "$LOCK" 2>/dev/null || fail 'Otra publicación está en curso.';LOCKED=1;fi
for i in "${!FILES[@]}";do
 BEFORE[$i]="$(state "$LIVE/${FILES[$i]}")"
 if [[ "${BEFORE[$i]}" == AUSENTE ]];then : > "$TMP/original.$i";else cp -p -- "$LIVE/${FILES[$i]}" "$TMP/original.$i";fi
done
if [[ "$MODE" == --restore ]];then
 no_links "$2";RESTORE="$(realpath -e "$2")"
 [[ "$(dirname "$RESTORE")" == "$BACKUPS" ]] || fail 'Respaldo fuera de la carpeta prevista.'
 no_links "$RESTORE/version.txt";[[ -f "$RESTORE/version.txt" && "$(<"$RESTORE/version.txt")" == "$VERSION" ]] || fail 'Respaldo de otra entrega.'
 for i in "${!FILES[@]}";do
  for file in "original.$i" "original.$i.sha256" "publicado.$i.sha256";do no_links "$RESTORE/$file";[[ -f "$RESTORE/$file" ]] || fail 'Respaldo incompleto.';done
  original="$(<"$RESTORE/original.$i.sha256")";published="$(<"$RESTORE/publicado.$i.sha256")"
  [[ ( "$original" == AUSENTE || "$original" =~ ^[a-f0-9]{64}$ ) && "$published" =~ ^[a-f0-9]{64}$ ]] || fail 'Respaldo alterado.'
  if [[ "$original" == AUSENTE ]];then [[ ! -s "$RESTORE/original.$i" ]] || fail 'Respaldo alterado.';else [[ "$(hash "$RESTORE/original.$i")" == "$original" ]] || fail 'Respaldo alterado.';fi
  RESTORE_HASH[$i]="$original"
  [[ "${BEFORE[$i]}" == "$published" || "${BEFORE[$i]}" == "$original" ]] || fail 'Archivo editado después de publicar. No se sobrescribe.'
  cp -p -- "$RESTORE/original.$i" "$TMP/stage.$i"
 done
else
 cat > "$TMP/patch.php" <<'IMPE_PATCH'
<?php
$c=json_decode(base64_decode(''),true,512,JSON_THROW_ON_ERROR);
$i=(int)$argv[1];$s=file_get_contents($argv[2]);$crlf=substr_count($s,"\r\n");
if($crlf&&$crlf!==substr_count($s,"\n"))throw new RuntimeException('Finales de línea mixtos.');
$s=str_replace("\r\n","\n",$s);
if(isset($c[$i]['pairs'])){
 foreach($c[$i]['pairs'] as [$old,$new]){
  if(substr_count($s,$new)===1)continue;
  if(substr_count($s,$new)!==0||substr_count($s,$old)!==1)throw new RuntimeException('Bloque personalizado o incompatible; no se sustituye el archivo completo.');
  $s=str_replace($old,$new,$s);
 }
}else{
 if($s!==''&&$s!==$c[$i]['content'])throw new RuntimeException('Archivo nuevo personalizado; no se sobrescribe.');
 $s=$c[$i]['content'];
}
if($crlf)$s=str_replace("\n","\r\n",$s);
if(file_put_contents($argv[3],$s)!==strlen($s))throw new RuntimeException('No se pudo preparar el archivo.');
IMPE_PATCH
 for i in "${!FILES[@]}";do php "$TMP/patch.php" "$i" "$TMP/original.$i" "$TMP/stage.$i" || fail 'Código incompatible. SITIO INTACTO.';if [[ "${BEFORE[$i]}" == AUSENTE ]];then chmod 0644 "$TMP/stage.$i";else chmod --reference="$TMP/original.$i" "$TMP/stage.$i";fi;done
fi
for i in "${!FILES[@]}";do php -l "$TMP/stage.$i" >/dev/null || fail 'Error de sintaxis en el servicio preparado.';done
for i in "${!FILES[@]}";do
 no_links "$LIVE/${FILES[$i]}";[[ "$(state "$LIVE/${FILES[$i]}")" == "${BEFORE[$i]}" ]] || fail 'Un archivo cambió durante la revisión.'
 AFTER[$i]="$(hash "$TMP/stage.$i")";if [[ "$MODE" == --restore ]];then AFTER[$i]="${RESTORE_HASH[$i]}";fi;[[ "${AFTER[$i]}" == "${BEFORE[$i]}" ]] || CHANGED+=("$i")
done
if [[ "${#CHANGED[@]}" == 0 ]];then echo 'OK: ya aplicado o restaurado. Ningún archivo reemplazado.';exit 0;fi
if [[ "$MODE" == --check ]];then echo 'OK: revisión compatible. Ecard y avisos de aliados: seis archivos. SITIO INTACTO. Sin envíos ni SQL.';exit 0;fi
if [[ "$MODE" == --apply ]];then
 mkdir -p "$BACKUPS";BACKUP="$BACKUPS/ecard-aliados-$(date +%Y%m%d-%H%M%S)-$$";(umask 077;mkdir "$BACKUP")
 for i in "${!FILES[@]}";do
  cp -p -- "$TMP/original.$i" "$BACKUP/original.$i";[[ "${BEFORE[$i]}" == AUSENTE || "$(hash "$BACKUP/original.$i")" == "${BEFORE[$i]}" ]] || fail 'Respaldo inconsistente.'
  printf '%s\n' "${BEFORE[$i]}" > "$BACKUP/original.$i.sha256";printf '%s\n' "${AFTER[$i]}" > "$BACKUP/publicado.$i.sha256"
 done
 printf '%s\n' "$VERSION" > "$BACKUP/version.txt"
fi
for i in "${CHANGED[@]}";do
 install="$LIVE/${FILES[$i]}.impe-ecard-aliados-$$";[[ ! -e "$install" && ! -L "$install" ]] || fail 'Existe un temporal de instalación.'
 INSTALLING="$i"
 if [[ "${AFTER[$i]}" != AUSENTE ]];then cp -p -- "$TMP/stage.$i" "$install";fi
 for j in "${CHANGED[@]}";do
  expected="${BEFORE[$j]}";for done_i in "${WRITTEN[@]}";do [[ "$done_i" != "$j" ]] || expected="${AFTER[$j]}";done
  no_links "$LIVE/${FILES[$j]}";[[ "$(state "$LIVE/${FILES[$j]}")" == "$expected" ]] || fail 'Un archivo cambió antes de instalar.'
 done
 WRITTEN+=("$i");if [[ "${AFTER[$i]}" == AUSENTE ]];then rm -f -- "$LIVE/${FILES[$i]}";else mv -f -- "$install" "$LIVE/${FILES[$i]}";fi;INSTALLING=-1
 [[ "$(state "$LIVE/${FILES[$i]}")" == "${AFTER[$i]}" ]] || fail 'Archivo instalado distinto.'
done
echo "OK: $MODE terminado. Ecard y avisos de aliados. Sin SQL ni cambios en datos de aliados o reuniones."
if [[ "$MODE" == --apply ]];then echo "Preparar lecturas: php $LIVE/tools/configurar_avisos_aliados.php --apply";echo "Respaldo: $BACKUP";printf 'Rollback: bash %q --restore %q\n' "$(realpath "$0")" "$BACKUP";fi
